import sys

def main():
    data = sys.stdin.read().split()
    n, x = int(data[0]), int(data[1])
    by_ip = {}
    for i in range(n):
        t = int(data[2 + 2 * i])
        ip = data[3 + 2 * i]
        by_ip.setdefault(ip, []).append(t)
    flagged = []
    for ip, ts in by_ip.items():
        if len(ts) <= x:
            continue
        ts.sort()
        lo = 0
        for hi in range(len(ts)):
            while ts[hi] - ts[lo] >= 600:
                lo += 1
            if hi - lo + 1 > x:
                flagged.append(ip)
                break
    flagged.sort()
    print('\n'.join(flagged) if flagged else 'NONE')

